"use strict";
// Actual localhost API and managed Chromium. Synthetic source evidence is generated by
// the real C fitter/replay; only a test-only listener may select a synthetic promotion policy.
const { test, expect, chromium } = require("@playwright/test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const { spawn, spawnSync } = require("node:child_process");
const { createHash } = require("node:crypto");

for (const controlled of [false, true]) {
  test(`research paper lifecycle: ${controlled ? "CONTROLLED synthetic promotion" : "production synthetic refusal"}, controls and recovery`, async ({ page, browser }) => {
    const repo = path.resolve(__dirname, "../..");
    const prefix = controlled ? "controlled-promotion" : "production-refusal";
    const evidence = path.join(process.env.ENTROPYTRADE_BROWSER_EVIDENCE, prefix);
    let workspace = process.env.ENTROPYTRADE_BROWSER_WORKSPACE + "-" + prefix;
    const python = process.env.ENTROPYTRADE_BROWSER_PYTHON || path.join(repo, ".venv/bin/python");
    const origin = `http://127.0.0.1:${Number(process.env.ENTROPYTRADE_BROWSER_PORT || 43215) + Number(controlled)}`;
    assert(path.isAbsolute(workspace) && workspace.startsWith(path.join(repo, "data/cache/")));
    assert(!fs.existsSync(workspace), "workspace must be new");
    assert(chromium.executablePath().startsWith(path.join(__dirname, ".browsers/")));
    fs.mkdirSync(evidence, { recursive: true });
    const metadata = path.join(evidence, "setup.json");
    const env = { PATH: "/usr/bin:/bin", TZ: "UTC", PYTHONNOUSERSITE: "1", PYTHONDONTWRITEBYTECODE: "1", OMP_NUM_THREADS: "1", OPENBLAS_NUM_THREADS: "1", PYTHONPATH: `${repo}/backend:${repo}/backend/src` };
    const receipt = { status: "running", browser: browser.version(), data_kind: "synthetic", controlled_promotion: controlled, screenshots: [], downloads: [], posts: [], page_errors: [], console_errors: [] };
    const save = () => fs.writeFileSync(path.join(evidence, "receipt.json"), JSON.stringify(receipt, null, 2));
    const pause = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
    let server, jobId, epoch = 0;
    page.on("pageerror", (error) => { receipt.page_errors.push(error.message); save(); });
    page.on("console", (message) => { if (message.type() === "error") { receipt.console_errors.push(message.text()); save(); } });
    page.on("request", (request) => { if (request.method() === "POST") { receipt.posts.push({ path: new URL(request.url()).pathname, body: request.postDataJSON() }); save(); } });
    async function start() {
      assert(!await fetch(origin + "/api/catalog").catch(() => null), "Port occupied");
      const log = fs.openSync(path.join(evidence, `server-${++epoch}.log`), "a");
      server = spawn(python, ["-m", "tests.integration.research_paper_fixture", "--workspace", workspace, "--port", origin.split(":").at(-1), "--metadata", metadata, ...(jobId ? ["--job-id", jobId] : []), ...(controlled ? ["--controlled-promotion"] : [])], { cwd: repo, env, stdio: ["ignore", log, log] });
      fs.closeSync(log);
      for (let n = 0; n < 600; n++) {
        if (server.exitCode !== null) throw new Error(`Listener exited ${server.exitCode}; inspect server-${epoch}.log`);
        if ((await fetch(origin + "/api/research").catch(() => null))?.ok) {
          jobId ||= JSON.parse(fs.readFileSync(metadata)).job_id;
          return;
        }
        await pause(100);
      }
      throw new Error("Research paper fixture startup timeout");
    }
    async function stop() {
      if (!page.isClosed()) await page.goto("about:blank");
      if (!server || server.exitCode !== null || server.signalCode !== null) return;
      server.kill("SIGINT");
      await new Promise((resolve) => server.exitCode !== null ? resolve() : server.once("exit", resolve));
    }
    async function shot(file) { await page.evaluate(() => window.scrollTo(0, 0)); await page.screenshot({ path: path.join(evidence, file), fullPage: true }); receipt.screenshots.push(file); save(); }
    async function download(name, file) {
      const waiting = page.waitForEvent("download");
      await page.getByRole("link", { name, exact: true }).click();
      await (await waiting).saveAs(path.join(evidence, file));
      const bytes = fs.readFileSync(path.join(evidence, file));
      receipt.downloads.push({ file, sha256: createHash("sha256").update(bytes).digest("hex") });
      save();
      return bytes;
    }
    async function post(url, body) {
      const catalog = await (await fetch(origin + "/api/catalog")).json();
      return fetch(origin + url, { method: "POST", headers: { "Content-Type": "application/json", Origin: origin, "X-EntropyTrade-CSRF": catalog.csrf_token }, body: JSON.stringify(body) });
    }
    try {
      await start();
      await page.goto(origin + `/#/research/${jobId}`);
      await page.getByRole("tab", { name: /Paper eligibility/ }).click();
      const proposal = page.locator('[data-paper-model="ridge"]');
      await expect(proposal).toBeVisible({ timeout: 30_000 });
      await expect(page.locator("#view").getByText(/CONTROLLED SYNTHETIC/).first()).toBeVisible();
      const paper = await (await fetch(`${origin}/api/research/jobs/${jobId}/paper`)).json();
      const ridge = paper.proposals.find((item) => item.model_family === "ridge");
      assert(ridge);
      assert.equal(paper.submission_enabled, false);
      const refs = { experiment_id: ridge.experiment_id, model_family: "ridge", interval_seconds: 300 };
      if (!controlled) {
        await expect(proposal.locator('[data-paper-eligible="false"]')).toBeVisible();
        await expect(proposal.getByRole("button", { name: "Start paper deployment" })).toBeDisabled();
        assert(paper.proposals.every((item) => item.eligible === false));
        assert(ridge.reasons.some((reason) => /authentic evidence/.test(reason)));
        const denied = await post(`/api/research/jobs/${jobId}/paper`, refs);
        assert.equal(denied.status, 409);
        assert.equal((await denied.json()).eligibility.eligible, false);
        assert.deepEqual(await (await fetch(origin + "/api/monitors")).json(), []);
        assert.equal(receipt.posts.length, 0, "the browser never tried a blocked deployment");
        await shot("production-paper-refusal.png");
      } else {
        assert.equal(ridge.eligible, true, JSON.stringify(ridge.reasons));
        await expect(proposal.getByRole("button", { name: "Start paper deployment" })).toBeEnabled();
        await proposal.getByRole("button", { name: "Start paper deployment" }).click();
        await expect(page).toHaveURL(/#\/paper\/[0-9a-f-]{36}$/);
        const id = new URL(page.url()).hash.split("/").at(-1);
        const panel = page.locator("#paper-deployment");
        await expect(panel.locator('[data-paper-status="active"]')).toBeVisible();
        await expect(panel.getByText(/CONTROLLED SYNTHETIC/)).toBeVisible();
        await expect(panel.getByRole("link", { name: jobId, exact: true })).toBeVisible();
        await expect.poll(async () => (await (await fetch(`${origin}/api/monitors/${id}`)).json()).paper_summary?.status, { timeout: 45_000 }).toBe("simulated");
        const committed = await (await fetch(`${origin}/api/monitors/${id}`)).json();
        assert(committed.paper_summary.fill_count > 0, "actual incoming observations must produce a computed simulated fill");
        assert(committed.paper_summary.positions.length > 0);
        await expect(panel.locator(".kv-row").filter({ has: page.getByText("Fills / settlements", { exact: true }) }).locator("dd")).toHaveText(`${committed.paper_summary.fill_count} / ${committed.paper_summary.settlement_count}`, { timeout: 15_000 });
        for (const [label, key] of [["Cash", "cash"], ["Fees paid", "fees"], ["Equity at cost", "equity_at_cost"], ["Current drawdown at cost", "drawdown_at_cost"], ["Peak equity at cost", "peak_equity_at_cost"]]) {
          const value = await panel.locator(".kv-row").filter({ has: page.getByText(label, { exact: true }) }).locator("dd").textContent();
          assert.equal(Number(value.replace("−", "-").replace(/[$,]/g, "")), Number(Number(committed.paper_summary[key]).toFixed(2)));
        }
        receipt.incoming = { cycles: committed.cycle_count, fills: committed.paper_summary.fill_count, positions: committed.paper_summary.positions.length, state_hash: committed.paper_summary.state_hash };
        save();
        await shot("incoming-paper-account.png");
        assert.deepEqual(receipt.posts.find((request) => request.path === `/api/research/jobs/${jobId}/paper`).body, refs);
        const duplicate = await post(`/api/research/jobs/${jobId}/paper`, refs);
        assert.equal(duplicate.status, 201);
        const existing = await duplicate.json();
        assert.equal(existing.id, id); assert.equal(existing.created, false);
        assert.equal((await (await fetch(origin + "/api/monitors")).json()).length, 1);
        await page.setViewportSize({ width: 375, height: 900 });
        await page.evaluate(() => window.scrollTo(0, 0));
        await expect(page.locator("#sidebar")).not.toBeInViewport();
        assert(await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth) <= 1);
        await shot("incoming-paper-mobile-controls.png");
        await panel.locator('[data-paper-action="pause"]').click();
        await expect(panel.locator('[data-paper-status="paused"]')).toBeVisible();
        await panel.locator('[data-paper-action="resume"]').click();
        await expect(panel.locator('[data-paper-status="active"]')).toBeVisible();
        await panel.locator('[data-paper-action="suspend"]').click();
        await expect(panel.locator('[data-paper-status="suspended"]')).toBeVisible();
        await expect(panel.locator('[data-paper-action="resume"]')).toHaveCount(0);
        const refusedResume = await post(`/api/monitors/${id}/resume`, {});
        assert.equal(refusedResume.status, 400);
        await panel.locator('[data-paper-action="cancel"]').click();
        await expect(panel.locator('[data-paper-status="cancelled"]')).toBeVisible();
        await expect(panel.locator("[data-paper-action]")).toHaveCount(0);
        await expect(page.getByRole("switch", { name: "Live trading (disabled)" })).toBeDisabled();
        const account = await download("Paper account JSON", "cancelled-account.json");
        const shadow = await download("Execution evidence JSON", "cancelled-evidence.json");
        const exported = JSON.parse(shadow);
        assert.equal(exported.source_kind, "autonomous_research");
        assert.equal(exported.research_job_id, jobId);
        assert.equal(exported.experiment_id, ridge.experiment_id);
        assert.equal(exported.model_binding.model_ref.version, ridge.model_hash);
        assert.equal(exported.submission_enabled, false);
        assert.equal(exported.status, "cancelled");
        await shot("paper-controls-and-provenance.png");
        await page.setViewportSize({ width: 375, height: 900 });
        await page.evaluate(() => window.scrollTo(0, 0));
        await expect(page.locator("#sidebar")).not.toBeInViewport();
        assert(await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth) <= 1);
        await shot("paper-mobile.png");
        await stop();
        await start();
        await page.goto(origin + `/#/paper/${id}`);
        await expect(panel.locator('[data-paper-status="cancelled"]')).toBeVisible();
        assert.deepEqual(await download("Paper account JSON", "restarted-account.json"), account);
        assert.deepEqual(await download("Execution evidence JSON", "restarted-evidence.json"), shadow);
        await stop();
        const archive = path.join(evidence, "workspace.zip");
        const snapshot = spawnSync(python, ["-m", "tests.integration.research_paper_fixture", "--recover", "snapshot", "--controlled-promotion", "--workspace", workspace, "--archive", archive], { cwd: repo, env, encoding: "utf8", timeout: 120_000 });
        assert.equal(snapshot.status, 0, snapshot.stdout + snapshot.stderr);
        workspace += "-restored";
        const restore = spawnSync(python, ["-m", "tests.integration.research_paper_fixture", "--recover", "restore", "--controlled-promotion", "--workspace", workspace, "--archive", archive], { cwd: repo, env, encoding: "utf8", timeout: 120_000 });
        assert.equal(restore.status, 0, restore.stdout + restore.stderr);
        receipt.restore = JSON.parse(restore.stdout); save();
        await start();
        await page.goto(origin + `/#/paper/${id}`);
        await expect(panel.locator('[data-paper-status="cancelled"]')).toBeVisible();
        assert.deepEqual(await download("Paper account JSON", "restored-account.json"), account);
        assert.deepEqual(await download("Execution evidence JSON", "restored-evidence.json"), shadow);
        await expect(panel.locator("[data-paper-action]")).toHaveCount(0);
        await page.goto(origin + `/#/research/${jobId}`);
        await page.getByRole("tab", { name: /Paper eligibility/ }).click();
        await expect(page.locator('[data-paper-model="ridge"]').getByRole("link", { name: "Open paper deployment", exact: true })).toBeVisible();
        await shot("restored-paper-source.png");
      }
    } catch (error) { receipt.status = "failed"; receipt.failure = error.stack; throw error; }
    finally {
      await stop();
      if (receipt.status !== "failed") {
        try { assert.deepEqual(receipt.page_errors, []); assert.deepEqual(receipt.console_errors, []); receipt.status = "passed"; }
        catch (error) { receipt.status = "failed"; receipt.failure = error.stack; save(); throw error; }
      }
      save();
    }
  });
}
